const locationRules =  $('SetProfileVector').first().json.profileVector.locationRules;
const workPreferences = $('SetProfileVector').first().json.profileVector.personalInfo.workPreferences;

const location =  $input.first().json.jobDescriptionData.location;

function classifyLocationType(location) {
  const city     = (location.city || '').toLowerCase();
  const country  = (location.country || '').toLowerCase();
  const remote   = (location.remote_type || '').toLowerCase();
  const restrict = (location.remote_restriction || '').toLowerCase();

  // Pure remote — check for restrictions
  if (remote === 'remote') {
    if (!restrict || restrict === '' || restrict === 'worldwide') {
      return 'REMOTE_EU_ELIGIBLE';
    }
    if (/united states|usa|us only/i.test(restrict)) return 'REMOTE_RESTRICTED_US';
    if (/united kingdom|uk only/i.test(restrict))    return 'REMOTE_RESTRICTED_UK';
    return 'REMOTE_RESTRICTED_OTHER';
  }

  // On-site or hybrid — classify by country
  const dach = ['austria', 'germany', 'switzerland'];
  if (dach.includes(country)) return 'EU_DACH';

  if (country === 'united kingdom' || country === 'uk') return 'UK';

  const apac = ['australia','singapore','japan','new zealand','hong kong'];
  if (apac.includes(country)) return 'APAC';

  // All other European countries
  const eu = ['france','netherlands','belgium','poland','spain','italy',
              'sweden','denmark','norway','finland','portugal','ireland',
              'czech republic','slovakia','hungary','romania','slovenia',
              'croatia','greece','luxembourg'];
  if (eu.includes(country)) return 'EU_OTHER';

  // Fallback — DeepSeek couldn't determine location clearly
  return 'REMOTE_EU_ELIGIBLE';
}

// Work authorization check
const visaStatus = workPreferences.visa_status || '';
const locationType = classifyLocationType(
  location
);

const noUsAuth = /no us|no american/i.test(visaStatus);
const noUkAuth = /no uk|no united kingdom|no british/i.test(visaStatus);

let workAuthWarning = null;
if (locationType === 'REMOTE_RESTRICTED_US' && noUsAuth) {
  workAuthWarning = 'This role requires US work authorization which your profile indicates you do not have.';
}
if (locationType === 'REMOTE_RESTRICTED_UK' && noUkAuth) {
  workAuthWarning = 'This role requires UK work authorization. Post-Brexit this affects EU citizens.';
}

// Get matching location rules from your lookup
const activeLocationRules = locationRules[locationType] 
                          || locationRules['REMOTE_EU_ELIGIBLE'];

return [{
  json: {
    locationType,
    workMode: location.remote_type,
    activeLocationRules,
    workAuthWarning
  }
}];

var config = {};

var filteredItems =  $input.all().filter(x => x.json["row_number"] > 4 && x.json["col_2"].trim() != "");

for (const item of filteredItems) {
  config[item.json["PIPELINE CONFIGURATION"]] = item.json["col_2"]
}

return {json:{config}};

var fitBranch = $input.first().json.fitScore;
var desireBranch = $input.first().json.desireScore;

var config = $('SetConfig').first().json.config;

const fitScore = fitBranch.fit_score;
const desireScore = desireBranch.desire_score;
const avgScore = (fitScore + desireScore) / 2;

const minFit = parseInt(config['Min Fit Score to Auto-Proceed'] || 10);
const minDesire = parseInt(config['Min Desire Score to Auto-Proceed'] || 8);
const priorityThreshold = parseInt(config['Priority Flag Threshold (avg Fit+Desire)'] || 15);

const shouldPause = fitScore < minFit || desireScore < minDesire;
const isPriority = avgScore >= priorityThreshold;

return [{
  json: {
    ...fitBranch,
    desireDecision: desireBranch.desire_decision,
    desireScore,
    fitScore,
    avgScore,
    shouldPause,
    isPriority,
    scores: { fit: fitScore, desire: desireScore, avg: avgScore }
  }
}];

