function deriveIntelligenceLevel(jd, company) {
  const seniority = jd.seniority_level;
  const stage     = company.funding_stage;
  const tone      = company.tone;
  const industry  = (company.industry_vertical || '').toLowerCase();

  // High: consulting, finance, legal, executive roles, formal enterprise
  if (['consulting', 'finance', 'legal', 'investment'].some(i => industry.includes(i))) return 'HIGH';
  if (['Director', 'VP', 'C-level', 'Principal'].includes(seniority)) return 'HIGH';
  if (tone === 'corporate') return 'HIGH';

  // Low: early startups, creative, gaming, consumer apps
  if (['seed', 'bootstrapped'].includes(stage) && tone === 'startup') return 'LOW';
  if (['gaming', 'consumer', 'creative', 'media'].some(i => industry.includes(i))) return 'LOW';

  // Medium: everything else — scale-ups, SaaS, tech companies
  return 'MEDIUM';
}

function deriveTone(company) {
  const stage  = company.funding_stage;
  const tone   = company.tone;

  if (tone === 'startup' && ['seed', 'series-a'].includes(stage)) {
    return 'conversational and direct — write like a sharp colleague, not a job applicant. First person, active voice, no filler phrases.';
  }
  if (tone === 'mission-driven') {
    return 'warm, purposeful, and grounded — show genuine connection to the mission without being sycophantic. Passion is earned through specifics, not adjectives.';
  }
  if (tone === 'technical') {
    return 'precise and evidence-led — let achievements speak. Minimal fluff. Technical credibility over soft language.';
  }
  if (tone === 'corporate' || tone === 'formal') {
    return 'professional and structured — formal register, third-person framing of achievements is acceptable, clear paragraph logic.';
  }
  return 'professional but human — confident without being stiff. Clear, specific, and direct.';
}

function isNoticePeriodSellingPoint(notice) {
  // Short notice periods are a selling point, long ones less so
  const lower = notice.toLowerCase();
  if (/immediate|immediately|2 week|1 month/i.test(lower)) return true;
  return false;
}

