var framingBrief = $('SetFramingBrief').first().json.framingBrief;
var cvLanguage = $('SetLanguageClassification').first().json.languageClassification.language || "English";

const coverLetterDecision = $('SetCoverLetterDecision').first().json.coverLetterDecision;
const targetGross = profile.personalInfo.salary.targetGross;
const preferredCurrency = profile.personalInfo.salary.salaryCurrencyPreference;

const intelligenceLevel = deriveIntelligenceLevel(jd, company);
const tone              = deriveTone(company);
const shouldAddressGap  = blockingGaps.length > 0 || significantGaps.length > 0;
const isSalaryExpected  = locationRules?.['gehaltsWunsch']?.toLowerCase().includes('yes');

// Assemble the raw data the AI will need
const briefData = {
  // Recipient
  company_name:         company.company_name_confirmed,
  position:             framingBrief.professional_title_for_cv,
  hiring_manager:       company.hiring_manager_name || null,
  hiring_manager_title: company.hiring_manager_title || null,

  // Language & format
  language:             cvLanguage,
  intelligence_level:   intelligenceLevel,
  formality:            intelligenceLevel === 'HIGH' ? 'formal'
                      : intelligenceLevel === 'LOW'  ? 'semi-formal'
                      : 'professional',
  max_words:            intelligenceLevel === 'HIGH' ? 350 : 280,

  // Company context
  mission_statement:    company.mission_statement,
  recent_news:          company.recent_news_sentiment === 'positive'
                          ? company.recent_news_headline : null,
  values_language:      company.values_keywords || [],
  culture_signals:      company.culture_signals || [],
  company_stage:        company.funding_stage,
  company_tone:         company.tone,

  // Opening
  opening_hook:         framingBrief.opening_hook_for_cover_letter,
  framing_angle:        framingBrief.framing_angle,

  // Strengths with evidence
  strengths:            fitResult.genuine_strengths.slice(0, 3).map(strength => ({
    strength,
    evidence: profile.quantifiedAchievementIndex
                .filter(a => a.skillTags?.some(t =>
                  strength.toLowerCase().includes(t.toLowerCase())
                ))
                .slice(0, 1)
                .map(a => a.achievement)[0] || null
  })),

  // Gap handling
  should_address_gap:   shouldAddressGap,
  gaps:                 [...blockingGaps, ...significantGaps].map(g => g.gap),
  gap_narrative:        fitResult.gap_narrative_for_cover_letter,

  // Closing
  specific_angle:       coverLetterDecision.cover_letter_angle,
  salary_expectation:   isSalaryExpected ? targetGross : null,
  notice_period:        isNoticePeriodSellingPoint(profile.personalInfo.workPreferences.preferredStartAvailability) ? profile.workPreferences.preferredStartAvailability : null,

  // ATS & mirroring
  ats_keywords:         framingBrief.ats_keywords_to_embed?.slice(0, 5) || [],
  company_language:     framingBrief.company_language_to_mirror || [],
};

return [{ json: { briefData } }];

