parameters.jsCode:
const briefData = $('Prepare Writingprompt Brief').first().json.briefData;
const brief = $('SetCoverLetterBrief').first().json.coverLetterBrief;
const profileVector = $('SetProfileVector').first().json.profileVector;
const fingerprint = $input.first().json.humanizerResult;

const systemMessage = `
You are writing a cover letter as ${profileVector.personalInfo.identity.name}.

This means: you are not describing this person. You ARE 
this person. First person throughout. Their achievements 
are your achievements. Their voice is your voice.

YOUR VOICE FOR THIS LETTER:
${brief.tone_description}

INTELLIGENCE LEVEL: ${brief.meta.intelligence_level}
${brief.meta.intelligence_description}

YOUR ABSOLUTE CONSTRAINTS:
- Maximum ${brief.meta.max_words} words. Count them. 
  Not one word more.
- Language: ${brief.meta.language} throughout.
- Every claim must be grounded in the provided evidence. 
  You may not invent metrics, achievements, or experiences.
- You may not use any phrase from the forbidden list.
- You may not use any generic from the specificity fingerprint.
- Every paragraph must use at least one company-specific 
  anchor and one candidate-specific anchor from the 
  fingerprint — this is not optional.

YOUR PRIMARY TEST:
After writing, ask yourself: could this opening sentence 
have been written for any other company? If yes, rewrite 
it until the answer is no.

WHAT SUCCESS LOOKS LIKE:
A recruiter who has read 200 applications today reads this 
letter and pauses. Not because it is clever, but because 
it is specific. They can see exactly why this person is 
writing to them and not to someone else.
`;

const prompt = `
Write the cover letter now.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
SPECIFICITY FINGERPRINT — use these, do not invent:

Company-specific anchors (must use at least 2):
${fingerprint.company_specific_anchors.map((a,i) =>
  `${i+1}. "${a.anchor}" — ${a.how_to_use}`
).join('\n')}

Candidate-specific anchors (must use at least 2):
${fingerprint.candidate_specific_anchors.map((a,i) =>
  `${i+1}. "${a.anchor}" — ${a.how_to_use}`
).join('\n')}

Intersection points (use at least 1):
${fingerprint.intersection_anchors.map((a,i) =>
  `${i+1}. Their need: ${a.company_need} ↔ Your evidence: ${a.candidate_evidence}`
).join('\n')}

Forbidden generics for this application (avoid these):
${fingerprint.forbidden_generics.map(g => `  ✗ "${g}"`).join('\n')}

Opening sentence candidates (choose one or write better):
${fingerprint.opening_sentence_candidates.map((s,i) =>
  `${i+1}. ${s}`
).join('\n')}

Closing sentence candidates (choose one or write better):
${fingerprint.closing_sentence_candidates.map((s,i) =>
  `${i+1}. ${s}`
).join('\n')}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
STRUCTURE TO FOLLOW:
${brief.structure.map(s => `${s.step}. ${s.element}: ${s.instruction}`).join('\n')}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
PARAGRAPH OUTLINE:
${brief.paragraph_outline.map(p => `
Paragraph ${p.number} — ${p.role}
Length: ${p.length}
How to open: ${p.opening_instruction}
Must include:
${p.must_include.map(i => `  • ${i}`).join('\n')}
Must NOT:
${p.must_not.map(i => `  ✗ ${i}`).join('\n')}
Flow: ${p.example_flow}
`).join('\n')}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
WRITING INSTRUCTIONS:
Voice:               ${brief.writing_instructions.voice}
Sentence complexity: ${brief.writing_instructions.sentence_complexity}
Vocabulary:          ${brief.writing_instructions.vocabulary_guidance}
Transitions:         ${brief.writing_instructions.paragraph_transitions}
Evidence:            ${brief.writing_instructions.how_to_use_evidence}
Close:               ${brief.writing_instructions.how_to_close}
${briefData.should_address_gap
  ? `Gap handling:   ${brief.writing_instructions.how_to_handle_gap}`
  : ''}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
ATS KEYWORDS — embed naturally, never as a list:
${brief.ats_keywords_to_embed?.join(', ') || 'none'}

COMPANY LANGUAGE TO MIRROR — use their words back at them:
${brief.company_language_to_mirror?.join(', ') || 'none'}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
PHRASES YOU MAY NOT USE:
${brief.avoid_phrases.map(p => `  ✗ "${p}"`).join('\n')}

PATTERNS YOU MAY NOT USE:
${brief.avoid_patterns.map(p => `  ✗ ${p}`).join('\n')}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Output only the letter text. Start with the salutation.
No meta-commentary. No "here is the letter". 
No explanation of choices made.
Word limit: ${brief.meta.max_words} words maximum.`;

return [{ json: { systemMessage, prompt } }];

return [{json: {
  draftLetter: $input.first().json.draft,
  detectionAttempt: 0
}}];

var detectionResult = $input.first().json.AIPatternDetectionResult;
var detectionAttempt = $('Prepare AI Detector Prompt').first().json.detectionAttempt;
return [{
  json: {
    detectionResult,
    aiPatternScore:           detectionResult.ai_pattern_score,
    requiresRewrite:          detectionResult.ai_pattern_score > 4,
    survivingHumanElements:   detectionResult.surviving_human_elements || [],
    detectionAttempt:         detectionAttempt + 1    
  }
}]

const detection = $('SetAIPatternDetectionResult').first().json.AIPatternDetectionResult;
const brief     = $('SetCoverLetterBrief').first().json.coverLetterBrief;
const fingerprint = $('SetHumanizerResult').first().json.humanizerResult;
const draftLetter = $('Prepare AI Detector Prompt').first().json.draftLetter;
const survivingHumanElements = $('Prepare check data').first().json.survivingHumanElements;

// Filter to blocking and significant flags only
const flagsToFix = detection.flags
  .filter(f => f.severity === 'blocking' || f.severity === 'significant');

const prompt = `
Perform surgical rewrites on these specific flagged passages.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
ORIGINAL LETTER:
${draftLetter}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
PASSAGES TO REWRITE (fix ONLY these):
${flagsToFix.map((f, i) => `
Fix ${i+1}:
  Text:      "${f.exact_text}"
  Problem:   ${f.why_it_sounds_ai}
  Direction: ${f.fix_direction}
  Location:  ${f.location}
`).join('\n')}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
HUMAN ELEMENTS TO PRESERVE (do not touch these):
${survivingHumanElements.map(e => `  • "${e}"`).join('\n')}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
EVIDENCE AVAILABLE FOR REWRITES:
Candidate anchors: 
${fingerprint.candidate_specific_anchors.map(a => `  • ${a.anchor}`).join('\n')}

Company anchors:
${fingerprint.company_specific_anchors.map(a => `  • ${a.anchor}`).join('\n')}

Intersection points:
${fingerprint.intersection_anchors.map(a => 
  `  • ${a.company_need} ↔ ${a.candidate_evidence}`
).join('\n')}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
LANGUAGE: ${brief.meta.language}
INTELLIGENCE LEVEL: ${brief.meta.intelligence_level}
MAX WORDS: ${brief.meta.max_words}

HUMAN WRITING MARKERS TO INTRODUCE where natural:
- Sentence fragments used deliberately for emphasis
- Variation in sentence length (short punch after a longer sentence)
- A moment of specificity so precise it could only come 
  from memory ("not just distributed systems — specifically 
  the moment we realised our monolith would never scale 
  past 5,000 transactions a day")
- Slightly imperfect parallelism (humans don't write 
  perfectly balanced three-part lists)

Return ONLY this JSON:
{
  "rewrites": [
    {
      "original": "",
      "replacement": "",
      "change_rationale": ""
    }
  ],
  "revised_letter": ""
}

revised_letter: the complete letter with all rewrites 
applied and all untouched sections preserved exactly.
Word count must not exceed ${brief.meta.max_words}.

IMPORTANT: OUTPUT FORMAT REQUIREMENTS

You MUST return ONLY valid JSON. 
Do NOT include any text before or after the JSON.
Do NOT wrap the JSON in markdown (no \`\`\`).
Do NOT add explanations, comments, or notes.
Do NOT include any keys that are not defined in the schema.
Do NOT rename fields.
Do NOT add an "output" or "response" wrapper.
Do NOT include trailing commas.

REMEMBER:
- ONLY JSON
- NO EXTRA TEXT
- NO FORMATTING

The response MUST be a single valid JSON object that strictly follows the provided schema! Anything else will result in a system error.`;

return [{ json: { prompt } }];

return [{json: {
  draftLetter: $input.first().json.output.revised_letter,
  detectionAttempt: $('Prepare check data').first().json.detectionAttempt
}}];

const brief     = $('SetCoverLetterBrief').first().json.coverLetterBrief;
const voiceCheck    = $input.first().json.output;
const draftLetter = $('Prepare AI Detector Prompt').first().json.draftLetter;
const wordCount     = draftLetter.split(/\s+/).filter(w => w.length > 0).length;
const overBy        = Math.max(0, wordCount - brief.meta.max_words);

const prompt = `
Apply final polish to this cover letter.

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
LETTER:
${draftLetter}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
TASKS — do ALL of these, do NOTHING else:

${voiceCheck.total_score < 80 && voiceCheck.fix_instruction
  ? `TASK 1 — Apply this fix (most important):
${voiceCheck.fix_instruction}
Weakest element identified: ${voiceCheck.weakest_element}

`
  : 'TASK 1 — No content fix needed (voice score above 80).\n\n'
}TASK 2 — Word count enforcement:
Current word count: ${wordCount}
Maximum allowed:    ${brief.meta.max_words}
${overBy > 0
  ? `Over by ${overBy} words. Remove the weakest sentence 
     in paragraph 2 or 3 — the one that adds the least 
     new information. Do not compress or summarise. 
     Cut the whole sentence.`
  : 'Word count is within limit. No cuts needed.'
}

TASK 3 — Language check:
Required language: ${brief.meta.language}
Check: is every sentence in ${brief.meta.language}?
If any sentence is in a different language, rewrite 
it in ${brief.meta.language} matching the surrounding tone.

TASK 4 — Formatting:
Salutation must be: ${brief.recipient.salutation}
${brief.meta.language === 'German' 
  ? 'Ensure Betreff line is present and bold-formatted with "Bewerbung als [position]".'
  : ''}
${brief.meta.language === 'Slovenian'
  ? 'Ensure Vi-form (vikanje) is used consistently throughout.'
  : ''}
Check: does the letter end with the correct sign-off 
for ${brief.meta.language} and ${brief.meta.formality} register?

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Output ONLY the final letter text.
Start with the salutation or Betreff (if German).
No word count note. No explanation. Nothing but the letter.
`;

return [{ json: { prompt } }];

const finalLetter =  $input.first().json.output.trim();
const finalWordCount = finalLetter.split(/\s+/).filter(w => w.length > 0).length;
const aiPatternDetector = $('SetAIPatternDetectionResult').first().json.AIPatternDetectionResult;
const voiceCheck = $('Voice And Authenticity Check').first().json.output;

return [{
  json: {
    finalCoverLetter: finalLetter,
    finalWordCount,
    pipeline_complete: true,
    quality_summary: {
      ai_pattern_score:  aiPatternDetector.ai_pattern_score,
      voice_score:       voiceCheck.total_score,
      would_shortlist:   voiceCheck.would_shortlist,
      detection_passes:  $('Prepare AI Detector Prompt').first().json.detectionAttempt,
      final_word_count:  finalWordCount
    }
  }
}];

// ── Pull all upstream data ─────────────────────────────────
const profile = $('SetProfileVector').first().json.profileVector;
const jd = $('SetNormalizedData').first().json.normalizedJobDescription;
const company = $('SetCompanyResearchData').first().json.companyResearchData;
const framingBrief = $('SetFramingBrief').first().json.framingBrief;
const locationType = $('SetLocationClassification').first().json.locationClassification.locationType;
const locationRules = $('SetLocationClassification').first().json.activeLocationRule;
const visualStrategy = $('SetVisualStrategy').first().json.visualStrategy;
const personalDecisions = $('SetPersonalDataAndProtoDecision').first().json.personalDataAndProtoDecision;
const skillSelection = $('SetSkillSelection').first().json.skillSelection;
const experienceSelection = $('SetSelectedExperiences').first().json.selectedExperiences;
const projectSelection  = $('SetSelectedProjects').first().json.projects;
const writtenJobs       = $('SetJobBullets').first().json.jobBullets.written_jobs;
const writtenProjects   = $('SetProjectDescriptions').first().json.projectDescriptions.written_projects;
const writtenSummary    = $('SetProfessionalSummary').first().json.professionalSummary;
const config = $('SetConfig').first().json.config;

// ── Helpers ────────────────────────────────────────────────
var cvLanguage = $('SetLanguageClassification').first().json.languageClassification.language || "English";

const maxPages    = parseInt(locationRules?.maxPages || 2);
const dateFormat  = locationRules?.dateFormat || 'MM/YYYY';
const pdfSize     = locationRules?.PdfPageSize || 'A4';

function formatDateStr(str) {
  // Input is always MM/YYYY from sheets, or "Present"/"Ongoing"
  if (!str) return '';
  const lower = str.toLowerCase();
  if (lower === 'present' || lower === 'ongoing') {
    return cvLanguage === 'German' ? 'heute'
         : cvLanguage === 'Slovenian' ? 'sedanjost'
         : 'Present';
  }
  const parts = str.split('/');
  if (parts.length !== 2) return str;
  const [month, year] = parts;
  if (dateFormat === 'DD.MM.YYYY') return `${month}.${year}`;
  if (dateFormat === 'DD/MM/YYYY') return `${month}/${year}`;
  return `${month}/${year}`;
}

function formatDateRange(start, end) {
  return `${formatDateStr(start)} – ${formatDateStr(end)}`;
}

function safeStr(val) {
  if (!val) return '';
  return String(val).trim();
}

function safeArr(val) {
  if (!val) return [];
  if (Array.isArray(val)) return val.filter(Boolean);
  if (typeof val === 'string') return val.split(',').map(s => s.trim()).filter(Boolean);
  return [];
}

// ── Section labels by language ─────────────────────────────
const labels = {
  English: {
    summary:          'Professional Summary',
    skills:           'Core Skills',
    experience:       'Work Experience',
    projects:         'Personal Projects',
    education:        'Education',
    certifications:   'Certifications',
    hobbies:          'Interests',
    languages:        'Languages',
    contact:          'Contact',
    references:       'References available on request',
    inProgress:       'In Progress',
    expires:          'Expires',
    noExpiry:         'No Expiry',
  },
  German: {
    summary:          'Profil',
    skills:           'Kenntnisse',
    experience:       'Berufserfahrung',
    projects:         'Projekte',
    education:        'Ausbildung',
    certifications:   'Zertifikate',
    hobbies:          'Interessen',
    languages:        'Sprachen',
    contact:          'Kontakt',
    references:       'Referenzen auf Anfrage',
    inProgress:       'In Bearbeitung',
    expires:          'Gültig bis',
    noExpiry:         'Unbefristet',
  },
  Slovenian: {
    summary:          'Profil',
    skills:           'Kompetence',
    experience:       'Delovne izkušnje',
    projects:         'Projekti',
    education:        'Izobrazba',
    certifications:   'Certifikati',
    hobbies:          'Interesi',
    references:       'Reference na zahtevo',
    inProgress:       'V teku',
    expires:          'Velja do',
    noExpiry:         'Brez roka',
  }
};
const L = labels[cvLanguage] || labels.English;

// ── META ──────────────────────────────────────────────────
const meta = {
  generated_at:   new Date().toISOString(),
  language:       cvLanguage,
  max_pages:      maxPages,
  pdf_size:       pdfSize,
  company:        safeStr(company.company_name_confirmed),
  position:       safeStr(framingBrief.professional_title_for_cv),
  location_type:  locationType,

  // Visual — from visualStrategy agent
  colors: {
    primary:   safeStr(visualStrategy.primary_color   || '1F3864'),
    secondary: safeStr(visualStrategy.secondary_color || '2E86AB'),
    tertiary:  safeStr(visualStrategy.tertiary_color  || 'F4F8FC'),
    accent:    safeStr(visualStrategy.accent_color    || 'E8A020'),
  },
  fonts: {
    heading: safeStr(visualStrategy.heading_font || 'Montserrat'),
    body:    safeStr(visualStrategy.body_font    || 'Inter'),
  },
  layout: {
    density:         safeStr(visualStrategy.layout_density   || 'balanced'),
    template_variant: safeStr(visualStrategy.template_variant || 'modern'),
    use_sidebar:     visualStrategy.use_sidebar === true,
    section_order:   Array.isArray(visualStrategy.section_order)
                       ? visualStrategy.section_order
                       : ['summary','experience','skills','projects','education','certifications'],
  },

  // Photo — from personalDataDecisions agent
  include_photo:  personalDecisions.include_photo === true,
  photo_url:      personalDecisions.include_photo === true
                    ? safeStr(profile.personalInfo.identity.photoUrl)
                    : null,
  photo_position: safeStr(personalDecisions.photo_position || 'top-right'),

  // Section labels for the template renderer
  labels: L,
};

// ── HEADER ────────────────────────────────────────────────
// Build contact line items — only include what exists and
// what location rules allow
const contactItems = [];

if (profile.personalInfo.identity.email) {
  contactItems.push({ type: 'email', value: profile.personalInfo.identity.email, icon: 'email' });
}
if (profile.personalInfo.identity.phone) {
  contactItems.push({ type: 'phone', value: profile.personalInfo.identity.phone, icon: 'phone' });
}

// Address depth per location rules
const addressDepth = safeStr(personalDecisions.address_depth || 'city-only');
if (addressDepth === 'city-only') {
  contactItems.push({ type: 'location', value: safeStr(profile.personalInfo.identity.location.city), icon: 'location' });
} else if (addressDepth === 'city-country') {
  contactItems.push({
    type: 'location',
    value: `${safeStr(profile.personalInfo.identity.location.city)}, ${safeStr(profile.personalInfo.location_country)}`,
    icon: 'location'
  });
}

if (profile.personalInfo.identity.linkedin) {
  contactItems.push({ type: 'linkedin', value: profile.personalInfo.identity.linkedin, icon: 'linkedin' });
}
if (profile.personalInfo.identity.github) {
  contactItems.push({ type: 'github', value: profile.personalInfo.identity.github, icon: 'github' });
}

// Languages — always include
if (profile.personalInfo.identity.languages && profile.personalInfo.identity.languages.length > 0) {
  contactItems.push({
    type: 'languages',
    value: Array.isArray(profile.personalInfo.identity.languages)
      ? profile.personalInfo.identity.languages.join(' · ')
      : profile.personalInfo.identity.languages,
    icon: 'language'
  });
}

const header = {
  name:            safeStr(profile.personalInfo.identity.name),
  title:           safeStr(framingBrief.professional_title_for_cv),
  contact_items:   contactItems,

  // Conditional per location rules
  dob:             personalDecisions.include_dob === true
                     ? safeStr(profile.personalInfo.identity.dateOfBirth) : null,
  nationality:     personalDecisions.include_nationality === true
                     ? safeStr(profile.personalInfo.identity.nationality) : null,
  driving_licence: personalDecisions.include_driving_licence === true
                     ? safeStr(profile.personalInfo.identity.drivingLicence) : null,
};

// ── SUMMARY ───────────────────────────────────────────────
const summary = safeStr(writtenSummary?.summary_text || '');

// ── SKILLS ────────────────────────────────────────────────
// Build display groups from skillSelection agent output
// Each group has a name and array of skill strings
let skillGroups = [];

if (skillSelection?.skills_display_groups?.length > 0) {
  skillGroups = skillSelection.skills_display_groups.map(group => ({
    group_name: safeStr(group.group_name),
    skills:     safeArr(group.skills),
  })).filter(g => g.skills.length > 0);
} else {
  // Fallback: split primary and secondary into two groups
  const primary   = safeArr(skillSelection?.primary_skills);
  const secondary = safeArr(skillSelection?.secondary_skills);
  if (primary.length > 0) {
    skillGroups.push({
      group_name: cvLanguage === 'German' ? 'Kerntechnologien' : 'Core Technologies',
      skills: primary,
    });
  }
  if (secondary.length > 0) {
    skillGroups.push({
      group_name: cvLanguage === 'German' ? 'Weitere Kenntnisse' : 'Additional Skills',
      skills: secondary,
    });
  }
}

// ── EXPERIENCE ────────────────────────────────────────────
// Merge written job content with selection metadata
// writtenJobs comes from the GPT-4o writing node
// experienceSelection tells us order and framing decisions

const selectedJobNumbers = (experienceSelection?.selected_jobs || [])
  .sort((a, b) => a.display_order - b.display_order)
  .map(s => s.job_number);

const experience = selectedJobNumbers.map(jobNum => {
  // Find written version
  const written = (writtenJobs || []).find(j => j.job_number === jobNum);
  // Find original profile data for fallback
  const original = profile.workExperience.find(j => j.job_number === jobNum);
  // Find selection metadata
  const selection = (experienceSelection?.selected_jobs || [])
    .find(s => s.job_number === jobNum);

  if (!written && !original) return null;

  // Compressed (old/minor jobs shown as one line)
  if (selection?.compress_to_summary || written?.is_compressed) {
    return {
      job_number:         jobNum,
      is_compressed:      true,
      title:            safeStr(written?.display_title || original?.title),
    company:          safeStr(written?.company_name  || original?.company),
    period:           safeStr(written?.date_range)
                      || formatDateRange(original?.start_date, original?.end_date),
    location:         safeStr(written?.location_display || original?.location),
    employment_type:  safeStr(original?.employment_type),
      compressed_summary: safeStr(
        written?.compressed_summary
        || `${safeStr(original?.title)} at ${safeStr(original?.company)} (${formatDateRange(original?.start_date, original?.end_date)})`
      ),
    };
  }

  // Full job entry
  const bullets = (written?.bullets || [])
    .map(b => typeof b === 'string' ? b : safeStr(b.text))
    .filter(b => b.length > 0);

  return {
    job_number:       jobNum,
    is_compressed:    false,
    title:            safeStr(written?.display_title || original?.title),
    company:          safeStr(written?.company_name  || original?.company),
    period:           safeStr(written?.date_range)
                      || formatDateRange(original?.start_date, original?.end_date),
    location:         safeStr(written?.location_display || original?.location),
    employment_type:  safeStr(original?.employment_type),
    bullets:          bullets,
    // Team/scope signals for template to show optionally
    direct_reports:   original?.direct_reports > 0 ? original.direct_reports : null,
    tech_stack:       safeArr(original?.tech_stack).slice(0, 8),
  };
}).filter(Boolean);

// ── PROJECTS ─────────────────────────────────────────────
// Only include if projects were selected
const selectedProjectNumbers = (projectSelection?.selected_projects || [])
  .sort((a, b) => a.display_order - b.display_order)
  .map(s => s.project_number);

const projects = selectedProjectNumbers.map(projNum => {
  const written  = (writtenProjects || []).find(p => p.project_number === projNum);
  const original = profile.projects.find(p => p.project_number === projNum);

  if (!written && !original) return null;

  return {
    project_number: projNum,
    name:           safeStr(written?.name || original?.name),
    tech_line:      safeStr(written?.tech_line || original?.tech_stack?.join(', ')),
    description:    safeStr(written?.description_line || original?.narrative_summary),
    impact:         safeStr(written?.impact_line || ''),
    url:            safeStr(written?.url || original?.public_url),
    status:         safeStr(written?.status || original?.status),
  };
}).filter(Boolean);

// ── EDUCATION ────────────────────────────────────────────
const education = (profile.education || []).map(edu => {
  // Dissertation: only include if recent or strong signal
  const yearEnd    = parseInt(edu.yearEnd) || 0;
  const currentYear = new Date().getFullYear();
  const yearsAgo   = currentYear - yearEnd;
  const showDissertation = edu.dissertationTitle
    && (yearsAgo < 8 || edu.strengthSignal === 'HIGH');

  // Key modules: max 6, only if degree is recent or highest
  const showModules = edu.keyModules?.length > 0 && yearsAgo < 10;

  return {
    degree_level:    safeStr(edu.degreeLevel),
    field:           safeStr(edu.field),
    degree_display:  `${safeStr(edu.degreeLevel)} ${safeStr(edu.field)}`.trim(),
    institution:     safeStr(edu.institution),
    location:        safeStr(edu.location),
    period:          `${safeStr(edu.yearStart)} – ${safeStr(edu.yearEnd)}`,
    grade:           safeStr(edu.grade),
    dissertation:    showDissertation ? safeStr(edu.dissertationTitle) : null,
    key_modules:     showModules ? safeArr(edu.keyModules).slice(0, 6) : [],
    awards:          safeStr(edu.awards),
    strength_signal: safeStr(edu.strengthSignal),
  };
});

// ── CERTIFICATIONS ───────────────────────────────────────
// Only active and in-progress, only High and Medium relevance
// Sorted: active HIGH first, then active MEDIUM, then in-progress
const certifications = (profile.certifications || [])
  .filter(c =>
    (c.status === 'ACTIVE' || c.status === 'IN_PROGRESS')
    && (c.relevance === 'HIGH' || c.relevance === 'MEDIUM')
  )
  .sort((a, b) => {
    const relevanceRank = { HIGH: 0, MEDIUM: 1 };
    const statusRank    = { ACTIVE: 0, IN_PROGRESS: 1 };
    const relDiff = (relevanceRank[a.relevance] || 1) - (relevanceRank[b.relevance] || 1);
    if (relDiff !== 0) return relDiff;
    return (statusRank[a.status] || 1) - (statusRank[b.status] || 1);
  })
  .slice(0, 6)
  .map(c => ({
    name:           safeStr(c.name),
    issuer:         safeStr(c.issuer),
    date_obtained:  safeStr(c.date_obtained),
    expiry:         c.expiry === 'No Expiry' || !c.expiry ? null : safeStr(c.expiry),
    no_expiry:      !c.expiry || c.expiry === 'No Expiry',
    credential_url: safeStr(c.credential_url),
    is_in_progress: c.status === 'IN_PROGRESS',
    expected_date:  c.status === 'IN_PROGRESS' ? safeStr(c.expected_date) : null,
    relevance:      safeStr(c.relevance),
    // Display string: "AWS · Mar 2022 · Expires Mar 2025"
    meta_line:      buildCertMetaLine(c, L),
  }));

function buildCertMetaLine(cert, labels) {
  const parts = [safeStr(cert.issuer)];
  if (cert.status === 'IN_PROGRESS') {
    parts.push(`${labels.inProgress} — ${safeStr(cert.expected_date)}`);
  } else {
    if (cert.date_obtained) parts.push(safeStr(cert.date_obtained));
    if (cert.expiry && cert.expiry !== 'No Expiry') {
      parts.push(`${labels.expires} ${safeStr(cert.expiry)}`);
    } else if (!cert.expiry || cert.expiry === 'No Expiry') {
      // Only show "No Expiry" for HIGH relevance certs — others don't need it
      if (cert.relevance === 'HIGH') parts.push(labels.noExpiry);
    }
  }
  return parts.filter(Boolean).join(' · ');
}

// ── HOBBIES ──────────────────────────────────────────────
const hobbies = personalDecisions.include_hobbies === true
  ? safeArr(personalDecisions.selected_hobbies)
  : [];

// ── FOOTER ───────────────────────────────────────────────
const footer = {
  gdpr_text:      personalDecisions.include_gdpr_footer === true
                    ? safeStr(personalDecisions.gdpr_footer_text)
                    : null,
  references_line: personalDecisions.include_references_line === true
                    ? safeStr(personalDecisions.references_line_text || L.references)
                    : null,
};

// ── FILE NAMES ────────────────────────────────────────────
const nameParts    = safeStr(profile.personalInfo.name).split(/\s+/);
const lastName     = nameParts.pop()  || 'CV';
const firstName    = nameParts.join('_') || '';
const companySlug  = safeStr(company.company_name_confirmed)
                       .replace(/[^a-zA-Z0-9]/g, '_')
                       .replace(/_+/g, '_')
                       .slice(0, 30);
const positionSlug = safeStr(framingBrief.professional_title_for_cv)
                       .replace(/[^a-zA-Z0-9]/g, '_')
                       .replace(/_+/g, '_')
                       .slice(0, 30);
const dateSlug     = new Date().toISOString().split('T')[0];

// ── FINAL DOCUMENT OBJECT ─────────────────────────────────
const documentJson = {
  meta,
  header,
  summary,
  skills:         skillGroups,
  experience,
  projects:       projects.length > 0 ? projects : null,
  education,
  certifications: certifications.length > 0 ? certifications : null,
  hobbies:        hobbies.length > 0 ? hobbies : null,
  footer,
};

// ── SANITY CHECKS ─────────────────────────────────────────
// Catch obvious data problems before sending to renderer
const warnings = [];

if (!documentJson.header.name) {
  warnings.push('WARN: header.name is empty');
}
if (!documentJson.header.title) {
  warnings.push('WARN: header.title is empty');
}
if (!documentJson.summary) {
  warnings.push('WARN: summary is empty');
}
if (documentJson.experience.length === 0) {
  warnings.push('WARN: no experience entries');
}
if (documentJson.skills.length === 0) {
  warnings.push('WARN: no skill groups');
}
if (documentJson.meta.include_photo && !documentJson.meta.photo_url) {
  warnings.push('WARN: include_photo is true but photo_url is empty');
  // Safe fallback — don't try to render a missing photo
  documentJson.meta.include_photo = false;
}
if (documentJson.experience.some(j => !j.is_compressed && j.bullets.length === 0)) {
  warnings.push('WARN: one or more non-compressed jobs have no bullets');
}

// ── OUTPUT ────────────────────────────────────────────────
return [{
  json: {
    documentJson,
    documentJsonString: JSON.stringify(documentJson),
    cvFileName:           `${lastName}_${firstName}_CV.pdf`.replace(/__+/g, '_'),
    coverLetterFileName:  `${lastName}_${firstName}_CoverLetter.pdf`.replace(/__+/g, '_'),
    folderName:           `${companySlug}_${positionSlug}_${dateSlug}`,
    assemblyWarnings:     warnings,
    assemblyComplete:     true,
  }}];

