  return `${preamble}

\\begin{document}

%% ── CV Header ───────────────────────────────────────────────
${header}

\\makecvheader

%% ── CV Body ─────────────────────────────────────────────────
${body}

%% ── Footer ──────────────────────────────────────────────────
${footer}

\\end{document}
`;
}


// ════════════════════════════════════════════════════════════
// SECTION 9 — EXECUTE & RETURN
