function deriveIntelligenceLevel(jd, company) {
  const seniority = jd.seniority_level;
  const stage     = company.funding_stage;
  const tone      = company.tone;
  const industry  = (company.industry_vertical || '').toLowerCase();

  // High: consulting, finance, legal, executive roles, formal enterprise
  if (['consulting', 'finance', 'legal', 'investment'].some(i => industry.includes(i))) return 'HIGH';
  if (['Director', 'VP', 'C-level', 'Principal'].includes(seniority)) return 'HIGH';
  if (tone === 'corporate') return 'HIGH';

  // Low: early startups, creative, gaming, consumer apps
  if (['seed', 'bootstrapped'].includes(stage) && tone === 'startup') return 'LOW';
  if (['gaming', 'consumer', 'creative', 'media'].some(i => industry.includes(i))) return 'LOW';

  // Medium: everything else — scale-ups, SaaS, tech companies
  return 'MEDIUM';
}

function deriveTone(company) {
  const stage  = company.funding_stage;
  const tone   = company.tone;

  if (tone === 'startup' && ['seed', 'series-a'].includes(stage)) {
    return 'conversational and direct — write like a sharp colleague, not a job applicant. First person, active voice, no filler phrases.';
  }
  if (tone === 'mission-driven') {
    return 'warm, purposeful, and grounded — show genuine connection to the mission without being sycophantic. Passion is earned through specifics, not adjectives.';
  }
  if (tone === 'technical') {
    return 'precise and evidence-led — let achievements speak. Minimal fluff. Technical credibility over soft language.';
  }
  if (tone === 'corporate' || tone === 'formal') {
    return 'professional and structured — formal register, third-person framing of achievements is acceptable, clear paragraph logic.';
  }
  return 'professional but human — confident without being stiff. Clear, specific, and direct.';
}

function isNoticePeriodSellingPoint(notice) {
  // Short notice periods are a selling point, long ones less so
  const lower = notice.toLowerCase();
  if (/immediate|immediately|2 week|1 month/i.test(lower)) return true;
  return false;
}

const profile = $('SetProfileVector').first().json.profileVector;
const jd = $('SetJobDescriptionData').first().json.jobDescriptionData;
const company = $('SetCompanyResearchData').first().json.companyResearchData;
const fitResult = $('SetScores').first().json.fitScore;
const blockingGaps = fitResult.genuine_gaps?.filter(g => g.severity === 'blocking') || [];
const significantGaps = fitResult.genuine_gaps?.filter(g => g.severity === 'significant') || [];
var locationRules = $('SetLocationClassification').first().json.activeLocationRule;
var framingBrief = $('SetFramingBrief').first().json.framingBrief;
var cvLanguage = $('SetLanguageClassification').first().json.languageClassification.language || "English";

const coverLetterDecision = $('SetCoverLetterDecision').first().json.coverLetterDecision;
const targetGross = profile.personalInfo.salary.targetGross;
const preferredCurrency = profile.personalInfo.salary.salaryCurrencyPreference;

const intelligenceLevel = deriveIntelligenceLevel(jd, company);
const tone              = deriveTone(company);
const shouldAddressGap  = blockingGaps.length > 0 || significantGaps.length > 0;
const isSalaryExpected  = locationRules?.['gehaltsWunsch']?.toLowerCase().includes('yes');

// Assemble the raw data the AI will need
const briefData = {
  // Recipient
  company_name:         company.company_name_confirmed,
  position:             framingBrief.professional_title_for_cv,
  hiring_manager:       company.hiring_manager_name || null,
  hiring_manager_title: company.hiring_manager_title || null,

  // Language & format
  language:             cvLanguage,
  intelligence_level:   intelligenceLevel,
  formality:            intelligenceLevel === 'HIGH' ? 'formal'
                      : intelligenceLevel === 'LOW'  ? 'semi-formal'
                      : 'professional',
  max_words:            intelligenceLevel === 'HIGH' ? 350 : 280,

  // Company context
  mission_statement:    company.mission_statement,
  recent_news:          company.recent_news_sentiment === 'positive'
                          ? company.recent_news_headline : null,
  values_language:      company.values_keywords || [],
  culture_signals:      company.culture_signals || [],
  company_stage:        company.funding_stage,
  company_tone:         company.tone,

  // Opening
  opening_hook:         framingBrief.opening_hook_for_cover_letter,
  framing_angle:        framingBrief.framing_angle,

  // Strengths with evidence
  strengths:            fitResult.genuine_strengths.slice(0, 3).map(strength => ({
    strength,
    evidence: profile.quantifiedAchievementIndex
                .filter(a => a.skillTags?.some(t =>
                  strength.toLowerCase().includes(t.toLowerCase())
                ))
                .slice(0, 1)
                .map(a => a.achievement)[0] || null
  })),

  // Gap handling
  should_address_gap:   shouldAddressGap,
  gaps:                 [...blockingGaps, ...significantGaps].map(g => g.gap),
  gap_narrative:        fitResult.gap_narrative_for_cover_letter,

  // Closing
  specific_angle:       coverLetterDecision.cover_letter_angle,
  salary_expectation:   isSalaryExpected ? targetGross : null,
  notice_period:        isNoticePeriodSellingPoint(profile.personalInfo.workPreferences.preferredStartAvailability) ? profile.workPreferences.preferredStartAvailability : null,

  // ATS & mirroring
  ats_keywords:         framingBrief.ats_keywords_to_embed?.slice(0, 5) || [],
  company_language:     framingBrief.company_language_to_mirror || [],
};

return [{ json: { briefData } }];

