function formatDateStr(str) {
  // Input is always MM/YYYY from sheets, or "Present"/"Ongoing"
  if (!str) return '';
  const lower = str.toLowerCase();
  if (lower === 'present' || lower === 'ongoing') {
    return cvLanguage === 'German' ? 'heute'
         : cvLanguage === 'Slovenian' ? 'sedanjost'
         : 'Present';
  }
  const parts = str.split('/');
  if (parts.length !== 2) return str;
  const [month, year] = parts;
  if (dateFormat === 'DD.MM.YYYY') return `${month}.${year}`;
  if (dateFormat === 'DD/MM/YYYY') return `${month}/${year}`;
  return `${month}/${year}`;
}

function formatDateRange(start, end) {
  return `${formatDateStr(start)} – ${formatDateStr(end)}`;
}

function safeStr(val) {
  if (!val) return '';
  return String(val).trim();
}

function safeArr(val) {
  if (!val) return [];
  if (Array.isArray(val)) return val.filter(Boolean);
  if (typeof val === 'string') return val.split(',').map(s => s.trim()).filter(Boolean);
  return [];
}

