parameters.jsCode:
// ============================================================
// AltaCV LaTeX Builder — n8n Code Node
// Converts structured CV JSON → complete compilable .tex document
// Compile with: latexmk -f -interaction=nonstopmode -pdfxe document.tex
// ============================================================

const cv = $input.first().json.documentJson;

// ════════════════════════════════════════════════════════════
// SECTION 1 — UTILITY HELPERS
// ════════════════════════════════════════════════════════════

/** Escape special LaTeX characters in plain text */
const escapeLatex = (str) => {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/\\/g,  '\\textbackslash{}')
    .replace(/&/g,   '\\&')
    .replace(/\$/g,  '\\$')
    .replace(/%/g,   '\\%')
    .replace(/#/g,   '\\#')
    .replace(/_/g,   '\\_')
    .replace(/\{/g,  '\\{')
    .replace(/\}/g,  '\\}')
    .replace(/~/g,   '\\textasciitilde{}')
    .replace(/\^/g,  '\\textasciicircum{}');
};

/** Strip leading # from a hex color string */
const stripHash = (hex) => (hex || '000000').replace(/^#/, '');

/** Return value or empty string if falsy */
const orEmpty = (val) => val ?? '';


// ════════════════════════════════════════════════════════════
// SECTION 2 — CONFIGURATION MAPS
// ════════════════════════════════════════════════════════════

/** Page margins (in cm) keyed by density setting */
const MARGINS_BY_DENSITY = {
  compact:  { left: 1.0,  right: 1.0,  top: 1.0,  bottom: 1.0,  columnsep: 1.0 },
  balanced: { left: 1.25, right: 1.25, top: 1.5,  bottom: 1.5,  columnsep: 1.2 },
  spacious: { left: 1.5,  right: 1.5,  top: 2.0,  bottom: 2.0,  columnsep: 1.5 },
};

/** Base font size keyed by template variant */
const FONTSIZE_BY_VARIANT = {
  classic: '11pt',
  modern:  '10pt',
  minimal: '10pt',
};

/** fontspec-compatible font names for XeLaTeX */
const FONT_NAME_MAP = {
  'Cormorant Garamond': 'Cormorant Garamond',
  'DM Sans':            'DM Sans',
  'Lato':               'Lato',
  'Roboto':             'Roboto',
  'Roboto Slab':        'Roboto Slab',
  'Inter':              'Inter',
  'Source Sans Pro':    'Source Sans 3',
  'Open Sans':          'Open Sans',
  'Raleway':            'Raleway',
};

/**
 * Maps human-readable section names (used in section_order) to
 * internal section keys used by the router below.
 * Add new mappings here for any new section name variants.
 */
const SECTION_NAME_TO_KEY = {
  'Summary':                                        'summary',
  'Professional Summary':                           'summary',
  'Profil':                                         'summary',
  'Experience':                                     'experience',
  'Work Experience':                                'experience',
  'Professional Experience':                        'experience',
  'Berufserfahrung':                                'experience',
  'Projects':                                       'projects',
  'Personal Projects':                              'projects',
  'Architecture & Technical Leadership Highlights': 'projects',
  'Education':                                      'education',
  'Ausbildung':                                     'education',
  'Education & Certifications':                     'education_and_certifications',
  'Certifications':                                 'certifications',
  'Zertifikate':                                    'certifications',
  'Skills':                                         'skills',
  'Technical Skills':                               'skills',
  'Technologien':                                   'skills',
  'Core Technical Competencies':                    'skills',
  'Kenntnisse':                                     'skills',
  'Languages':                                      'languages',
  'Sprachen':                                       'languages',
  'Interests':                                      'hobbies',
  'Hobbies':                                        'hobbies',
  'Interessen':                                     'hobbies',
};

/**
 * In sidebar mode, these sections go into the right (narrow) column.
 * Everything else goes into the left (wide) column.
 */
const SIDEBAR_SECTION_KEYS = new Set([
  'skills',
  'languages',
  'certifications',
  'education',
  'education_and_certifications',
  'hobbies',
]);

/** CEFR level and keyword → numeric cvskill rating (1–5) */
const LANGUAGE_LEVEL_TO_RATING = {
  'Native':       5,
  'Mutterspache': 5,
  'C2':           5,
  'C1':           4.5,
  'B2':           4,
  'B1':           3,
  'A2':           2,
  'A1':           1,
};


// ════════════════════════════════════════════════════════════
// SECTION 3 — CONTACT / HEADER SECTION BUILDERS
// ════════════════════════════════════════════════════════════

/** Render a single \printinfo line for one contact item */
function buildOneContactItem(item) {
  const val = escapeLatex(item.value);

  const normalizeUrl = (raw, prefix) =>
    raw.startsWith('http') ? raw : `${prefix}${raw}`;

  switch (item.type) {
    case 'email':
      return `  \\email{${item.value}}`;

    case 'phone':
      return `  \\phone{${item.value}}`;

    case 'location':
      return `  \\location{${val}}`;

    case 'linkedin': {
      const display = item.value.replace(/https?:\/\/(www\.)?linkedin\.com\/in\//i, '');
      return `  \\linkedin{${display}}`;
    }

    case 'github': {
      const display = item.value.replace(/https?:\/\/(www\.)?github\.com\//i, '');
      return `  \\github{${display}}`;
    }

    case 'website': {
      return `  \\homepage{${val}}`;
    }

    case 'xing': {
      const display = item.value.replace(/https?:\/\/(www\.)?xing\.com\/profile\//i, '');
      const url     = normalizeUrl(item.value, 'https://xing.com/profile/');
      return `  \\printinfo{\\faXing}{${escapeLatex(display)}}[${url}]`;
    }

    // 'languages' type is intentionally excluded here — rendered as its own section
    default:
      return `  \\printinfo{\\faInfo}{${val}}{}`;
  }
}

/** Build the full \personalinfo{} block including optional DOB/nationality/licence */
function buildPersonalInfoBlock(header) {
  const { contact_items = [], dob, nationality, driving_licence } = header;

  // Contact items — skip 'languages'; that goes in its own CV section
  const contactLines = contact_items
    .filter(item => item.type !== 'languages')
    .map(buildOneContactItem);

  // Optional demographic fields
  if (dob)              contactLines.push(`  \\printinfo{\\faBirthdayCake}{${escapeLatex(dob)}}{}`);
  if (nationality)      contactLines.push(`  \\printinfo{\\faFlag}{${escapeLatex(nationality)}}{}`);
  if (driving_licence)  contactLines.push(`  \\printinfo{\\faCar}{Licence ${escapeLatex(driving_licence)}}{}`);

  return `\\personalinfo{%\n${contactLines.join('\n')}\n}`;
}

/** Build the header block: name, tagline, optional photo, personalinfo */
function buildCvHeader(header, meta) {
  const includePhoto  = meta.include_photo  ?? false;
  const photoPosition = meta.photo_position ?? 'top-right';

  const photoCommand = includePhoto
    ? (photoPosition === 'top-left' ? '\\photoL{2.8cm}{{PROFILE_IMAGE}}' : '\\photoR{2.8cm}{{PROFILE_IMAGE}}')
    : '';

  return [
    `\\name{${escapeLatex(header.name)}}`,
    `\\tagline{${escapeLatex(header.title)}}`,
    photoCommand,
    buildPersonalInfoBlock(header),
  ].filter(Boolean).join('\n');
}


// ════════════════════════════════════════════════════════════
// SECTION 4 — CONTENT SECTION BUILDERS
// Each builder returns a LaTeX string or '' if data is missing.
// ════════════════════════════════════════════════════════════

// ── Summary ─────────────────────────────────────────────────

function buildSummarySection(summaryText, label) {
  if (!summaryText) return '';
  const paragraphs = summaryText.split('\n').filter(Boolean);
  return `\\cvsection{${escapeLatex(label)}}

${paragraphs.map(escapeLatex).join('\\\\\n')}`;
}

// ── Skills ──────────────────────────────────────────────────

function buildOneSkillGroup(group) {
  const items = (group.skills || [])
    .map(skill => {
      const name = typeof skill === 'string' ? skill : skill.name;
      return `  \\item ${escapeLatex(name)}`;
    })
    .join('\n');

  return `{\\color{emphasis}\\textbf{${escapeLatex(group.group_name)}}}\\\\[2pt]
\\begin{itemize}[leftmargin=*, label={\\color{accent}\\small$\\bullet$}]
${items}
\\end{itemize}`;
}

function buildSkillsSection(skills, label, useSidebar) {  
    if(useSidebar){
      return buildSkillsSectionForMultiColumn(skills, label);  
    }
  else{
      return buildSkillSelectionForSingleColumn(skills, label);
  }
}

function buildSkillsSectionForMultiColumn(skills, label) {
  if (!skills || skills.length === 0) return '';
  const groups = skills.map(buildOneSkillGroup).join('\n\n\\medskip\n');
  return `\\cvsection{${escapeLatex(label)}}

${groups}`;
}

function buildSkillSelectionForSingleColumn(skills, label) {
  if (!skills || skills.length === 0) return '';
  const grouped = skills.map(skill => {
    return '\n\\begin{minipage}[t]{\\linewidth}\n'+buildOneSkillGroup(skill)+'\n\\end{minipage}\n';
  });

  const result = grouped.reduce((groups, item, index) =>{
    const groupIndex = Math.floor(index / 2);
    if (!groups[groupIndex]) {
      groups[groupIndex] = [];
    }
    groups[groupIndex].push(item);
    return groups;
  }, [])
  .map(group => group.join('\n&\n'))
  .join('\n\\\\[8pt]\n');

  return `\n\\cvsection{${escapeLatex(label)}}\n\n\\begin{tabular}{@{}p{0.48\\textwidth}@{\\hspace{0.04\\textwidth}}p{0.48\\textwidth}@{}}\n ${result} \n\\end{tabular}\n`;
}

// ── Experience ───────────────────────────────────────────────

function buildOneExperienceItem(job) {
  // Compressed entry (e.g. early-career catch-all)
  if (job.is_compressed) {
      return `\n\\begin{quote}
      {\\small\\textbf{${escapeLatex(job.title)} at ${escapeLatex(job.company)} ( ${escapeLatex(job.period)} )}}
      {\\small\\textit{${escapeLatex(job.compressed_summary)}}}
      \\end{quote}\n`;
  }

  const bulletLines = (job.bullets || [])
    .map(b => `  \\item ${escapeLatex(b)}`)
    .join('\n');

  return `\\cvevent{${escapeLatex(job.title)}}{${escapeLatex(job.company)}}{${escapeLatex(job.period)}}{${escapeLatex(job.location)}}
\\begin{itemize}
${bulletLines}
\\end{itemize}`;
}

function buildExperienceSection(experience, label) {
  if (!experience || experience.length === 0) return '';

  // Sort by job_number descending so most recent appears first
  const sorted = [...experience].sort((a, b) => (b.job_number ?? 0) - (a.job_number ?? 0));
  const items  = sorted.map(buildOneExperienceItem).join('\n\n\\divider\n\n');

  return `\\cvsection{${escapeLatex(label)}}

${items}`;
}

// ── Projects ─────────────────────────────────────────────────

function buildOneProjectItem(project) {
  const lines = [
    `\\cvevent{${escapeLatex(project.name)}}{}{}{}`,
  ];

  if (project.tech_line) {
    lines.push(`{\\small\\color{emphasis}\\textbf{Stack:} ${escapeLatex(project.tech_line)}}\\\\[2pt]`);
  }
  if (project.description) {
    lines.push(escapeLatex(project.description));
  }
  if (project.impact) {
    lines.push(`\\\\[2pt]{\\small\\color{accent}${escapeLatex(project.impact)}}`);
  }
  if (project.url) {
    const url = project.url.startsWith('http') ? project.url : `https://${project.url}`;
    lines.push(`\\\\[2pt]\\printinfo{\\faGlobe}{${escapeLatex(project.url)}}[${url}]`);
  }

  return lines.join('\n');
}

function buildProjectsSection(projects, label) {
  if (!projects || projects.length === 0) return '';

  const sorted = [...projects].sort((a, b) => (a.project_number ?? 0) - (b.project_number ?? 0));
  const items  = sorted.map(buildOneProjectItem).join('\n\n\\divider\n\n');

  return `\\cvsection{${escapeLatex(label)}}

${items}`;
}

// ── Education ────────────────────────────────────────────────

function buildOneEducationItem(edu) {
  const lines = [
    `\\cvevent{${escapeLatex(edu.degree_display)}}{${escapeLatex(edu.institution)}}{${escapeLatex(edu.period)}}{${escapeLatex(edu.location)}}`,
  ];

  if (edu.dissertation) lines.push(`Thesis: \\textit{${escapeLatex(edu.dissertation)}}`);
  if (edu.grade)        lines.push(`Grade: ${escapeLatex(edu.grade)}`);
  if (edu.awards)       lines.push(escapeLatex(edu.awards));

  if (edu.key_modules && edu.key_modules.length > 0) {
    lines.push(`Key Modules: ${edu.key_modules.map(escapeLatex).join(', ')}`);
  }

  return lines.join('\\\\\n');
}

function buildEducationSection(education, label) {
  if (!education || education.length === 0) return '';
  const items = education.map(buildOneEducationItem).join('\n\n\\divider\n\n');
  return `\\cvsection{${escapeLatex(label)}}

${items}`;
}

// ── Certifications ───────────────────────────────────────────

function buildOneCertificationItem(cert) {
  const progressFlag = cert.is_in_progress
    ? ` {\\small\\color{accent}(${escapeLatex(orEmpty(cert.meta_line) || 'In Progress')})}`
    : '';
  const issuer = cert.issuer ? escapeLatex(cert.issuer) : '';
  return `\\cvachievement{\\faCertificate}{${escapeLatex(cert.name)}${progressFlag}}{${issuer}}`;
}

function buildCertificationsSection(certifications, label) {
  if (!certifications || certifications.length === 0) return '';
  const items = certifications.map(buildOneCertificationItem).join('\n\n\\divider\n\n');
  return `\\cvsection{${escapeLatex(label)}}

${items}`;
}

// ── Languages ────────────────────────────────────────────────

/**
 * Languages are stored as a contact_item with type='languages'.
 * Value format: "English (C2), German (C1) · Slovenian (Native)"
 * We parse these and render with \cvskill + numeric ratings.
 */
function buildLanguagesSection(contactItems, label) {
  const langItem = (contactItems || []).find(c => c.type === 'languages');
  if (!langItem) return '';

  const entries = langItem.value
    .split(/[,·]/)
    .map(s => s.trim())
    .filter(Boolean);

  const skillLines = entries.map(entry => {
    const match = entry.match(/^(.+?)\s*\(([^)]+)\)$/);
    if (match) {
      const name   = match[1].trim();
      const level  = match[2].trim();
      const rating = LANGUAGE_LEVEL_TO_RATING[level] ?? 3;
      return `\\cvskill{${escapeLatex(name)}}{${rating}}`;
    }
    return `\\cvskill{${escapeLatex(entry)}}{3}`;
  });

  return `\\cvsection{${escapeLatex(label)}}

${skillLines.join('\n\\divider\n')}`;
}

// ── Hobbies / Interests ───────────────────────────────────────

function buildHobbiesSection(hobbies, label) {
  if (!hobbies || hobbies.length === 0) return '';
  const tags = hobbies.map(h => `\\cvtag{${escapeLatex(h)}}`).join('\n');
  return `\\cvsection{${escapeLatex(label)}}

${tags}`;
}

// ── Footer ────────────────────────────────────────────────────

function buildFooterBlock(footer) {
  if (!footer) return '';
  const lines = [];

  if (footer.references_line) {
    lines.push(`\\begin{center}\\small\\textit{${escapeLatex(footer.references_line)}}\\end{center}`);
  }
  if (footer.gdpr_text) {
    lines.push(`\\begin{center}\\tiny\\color{body}${escapeLatex(footer.gdpr_text)}\\end{center}`);
  }

  return lines.join('\n');
}


// ════════════════════════════════════════════════════════════
// SECTION 5 — SECTION ROUTER
// Maps an internal section key → rendered LaTeX block
// ════════════════════════════════════════════════════════════

function renderSection(sectionKey, cv, useSidebar) {
  const labels = cv.meta.labels ?? {};
  switch (sectionKey) {
    case 'summary':
      return buildSummarySection(cv.summary, labels.summary ?? 'Summary');

    case 'skills':
      return buildSkillsSection(cv.skills, labels.skills ?? 'Skills', useSidebar ?? false);

    case 'experience':
      return buildExperienceSection(cv.experience, labels.experience ?? 'Experience');

    case 'projects':
      return buildProjectsSection(cv.projects, labels.projects ?? 'Projects');

    case 'education':
      return buildEducationSection(cv.education, labels.education ?? 'Education');

    case 'certifications':
      return buildCertificationsSection(cv.certifications, labels.certifications ?? 'Certifications');

    case 'education_and_certifications':
      // Render education first, then certifications, under their own headings
      return [
        buildEducationSection(cv.education, labels.education ?? 'Education'),
        buildCertificationsSection(cv.certifications, labels.certifications ?? 'Certifications'),
      ].filter(Boolean).join('\n\n');

    case 'languages':
      return buildLanguagesSection(cv.header?.contact_items, labels.languages ?? 'Languages');

    case 'hobbies':
      return buildHobbiesSection(cv.hobbies, labels.hobbies ?? 'Interests');

    default:
      return ''; // Unknown key — render nothing
  }
}


// ════════════════════════════════════════════════════════════
// SECTION 6 — PREAMBLE BUILDER
// ════════════════════════════════════════════════════════════

function buildPreamble(meta) {
  const layout     = meta.layout ?? {};
  const colors     = meta.colors ?? {};
  const fonts      = meta.fonts  ?? {};
  const useSidebar = layout.use_sidebar ?? false;

  const margins    = MARGINS_BY_DENSITY[layout.density]          ?? MARGINS_BY_DENSITY.balanced;
  const fontSize   = FONTSIZE_BY_VARIANT[layout.template_variant] ?? '10pt';
  const headingFont = FONT_NAME_MAP[fonts.heading] ?? fonts.heading ?? 'Lato';
  const bodyFont    = FONT_NAME_MAP[fonts.body]    ?? fonts.body    ?? 'Lato';

  // geometry arguments — columnsep only meaningful in 2-col mode
  const geometryParts = [
    `left=${margins.left}cm`,
    `right=${margins.right}cm`,
    `top=${margins.top}cm`,
    `bottom=${margins.bottom}cm`,
    ...(useSidebar ? [`columnsep=${margins.columnsep}cm`] : []),
  ];

  return `\\documentclass[${fontSize},a4paper,withhyper]{altacv}
%% AltaCV — auto-generated. Compile with:
%% latexmk -f -interaction=nonstopmode -pdfxe document.tex

% ── Page layout ─────────────────────────────────────────────
\\geometry{${geometryParts.join(',')}}
${useSidebar ? '\\usepackage{paracol}' : '% single-column layout — paracol not needed'}

% ── Fonts ───────────────────────────────────────────────────
\\iftutex
  % XeLaTeX / LuaLaTeX: load fonts by name via fontspec
  \\setmainfont{${headingFont}}
  \\setsansfont{${bodyFont}}
  \\renewcommand{\\familydefault}{\\sfdefault}
\\else
  % pdfLaTeX fallback
  \\usepackage[utf8]{inputenc}
  \\usepackage[T1]{fontenc}
  \\usepackage[defaultsans]{lato}
  \\renewcommand{\\familydefault}{\\sfdefault}
\\fi

% ── Named colors (from JSON) ─────────────────────────────────
\\definecolor{cvPrimary}{HTML}{${stripHash(colors.primary)}}
\\definecolor{cvSecondary}{HTML}{${stripHash(colors.secondary)}}
\\definecolor{cvTertiary}{HTML}{${stripHash(colors.tertiary)}}
\\definecolor{cvAccent}{HTML}{${stripHash(colors.accent)}}

% ── AltaCV semantic color aliases ───────────────────────────
\\colorlet{name}{black}
\\colorlet{tagline}{cvPrimary}
\\colorlet{heading}{cvPrimary}
\\colorlet{headingrule}{cvSecondary}
\\colorlet{subheading}{cvPrimary}
\\colorlet{accent}{cvAccent}
\\colorlet{emphasis}{cvPrimary}
\\colorlet{body}{black}

% ── Typography tweaks ────────────────────────────────────────
\\renewcommand{\\namefont}{\\Huge\\rmfamily\\bfseries}
\\renewcommand{\\personalinfofont}{\\footnotesize}
\\renewcommand{\\cvsectionfont}{\\LARGE\\rmfamily\\bfseries}
\\renewcommand{\\cvsubsectionfont}{\\large\\bfseries}
\\renewcommand{\\cvItemMarker}{{\\small\\textbullet}}
\\renewcommand{\\cvRatingMarker}{\\faCircle}`;
}


// ════════════════════════════════════════════════════════════
// SECTION 7 — DOCUMENT BODY BUILDER
// Handles both single-column and two-column (sidebar) layouts
// ════════════════════════════════════════════════════════════

/**
 * Resolve section_order strings → deduplicated internal keys.
 * Unknown section names are silently skipped.
 *
 * Special rule: 'languages' is always injected immediately before
 * 'education' (or 'education_and_certifications'), even if it was
 * not listed in section_order. This guarantees consistent placement
 * regardless of what the JSON contains.
 */
function resolveSectionOrder(sectionOrder) {
  const seen = new Set();

  // First pass: resolve names → keys, deduplicate
  const keys = (sectionOrder ?? [])
    .map(name => SECTION_NAME_TO_KEY[name] ?? null)
    .filter(key => {
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });

  // Second pass: ensure 'languages' appears directly before the
  // first education-type key. If languages is already in the list,
  // move it to that position. If it's absent, insert it there.
  const educationKeys = new Set(['education', 'education_and_certifications']);
  const educationIndex = keys.findIndex(k => educationKeys.has(k));

  if (educationIndex !== -1) {
    // Remove languages from wherever it currently sits (if present)
    const existingLanguagesIndex = keys.indexOf('languages');
    if (existingLanguagesIndex !== -1) {
      keys.splice(existingLanguagesIndex, 1);
    }
    // Re-find education index after possible removal, then insert before it
    const newEducationIndex = keys.findIndex(k => educationKeys.has(k));
    keys.splice(newEducationIndex, 0, 'languages');
  }

  return keys;
}

function buildDocumentBody(cv) {
  const useSidebar   = cv.meta.layout?.use_sidebar ?? false;
  const sectionOrder = cv.meta.layout?.section_order ?? [];
  const sectionKeys  = resolveSectionOrder(sectionOrder);

  if (useSidebar) {
    const mainKeys    = sectionKeys.filter(key => !SIDEBAR_SECTION_KEYS.has(key));
    const sidebarKeys = sectionKeys.filter(key =>  SIDEBAR_SECTION_KEYS.has(key));

    const mainContent = mainKeys
      .map(key => renderSection(key, cv, useSidebar))
      .filter(Boolean)
      .join('\n\n');

    const sidebarContent = sidebarKeys
      .map(key => renderSection(key, cv, useSidebar))
      .filter(Boolean)
      .join('\n\n');

    return `%% Two-column layout
\\columnratio{0.6}
\\begin{paracol}{2}

%% ── Left column (main content) ──────────────────────────────
${mainContent}

\\switchcolumn

%% ── Right column (sidebar) ──────────────────────────────────
${sidebarContent}

\\end{paracol}`;

  } else {
    // Single column — render sections in specified order
    return sectionKeys
      .map(key => renderSection(key, cv, useSidebar))
      .filter(Boolean)
      .join('\n\n');
  }
}


// ════════════════════════════════════════════════════════════
// SECTION 8 — FINAL ASSEMBLER
// ════════════════════════════════════════════════════════════

function buildFullLatexDocument(cv) {
  const preamble = buildPreamble(cv.meta);
  const header   = buildCvHeader(cv.header, cv.meta);
  const body     = buildDocumentBody(cv);
  const footer   = buildFooterBlock(cv.footer);

  return `${preamble}

\\begin{document}

%% ── CV Header ───────────────────────────────────────────────
${header}

\\makecvheader

%% ── CV Body ─────────────────────────────────────────────────
${body}

%% ── Footer ──────────────────────────────────────────────────
${footer}

\\end{document}
`;
}


// ════════════════════════════════════════════════════════════
// SECTION 9 — EXECUTE & RETURN
// ════════════════════════════════════════════════════════════

const latexDocument = buildFullLatexDocument(cv);

const base64LatexDocument = Buffer.from(latexDocument, "utf-8").toString("base64");

return [{ 
  json: { 
      template: latexDocument,
      base64: base64LatexDocument,
      imageUrl: $input.first().json.documentJson.meta.photo_url } }];

// ============================================================
// AltaCV LaTeX Builder — n8n Code Node
// Converts structured CV JSON → complete compilable .tex document
// Compile with: latexmk -f -interaction=nonstopmode -pdfxe document.tex
// ============================================================

const cv = {
  ...$("Prepare CV Template Data").all()[0].json.documentJson,
  ...$input.first().json
};

const kindRegardsInLanguages = {
  "German":"Mit freundlichen Grüßen",
  "Slovenian":"Lep pozdrav",
  "English":"Kind regards"
}

// ════════════════════════════════════════════════════════════
// SECTION 1 — UTILITY HELPERS
// ════════════════════════════════════════════════════════════

/** Escape special LaTeX characters in plain text */
const escapeLatex = (str) => {
  if (str === null || str === undefined) return '';
  return String(str)
    .replace(/\\/g,  '\\textbackslash{}')
    .replace(/&/g,   '\\&')
    .replace(/\$/g,  '\\$')
    .replace(/%/g,   '\\%')
    .replace(/#/g,   '\\#')
    .replace(/_/g,   '\\_')
    .replace(/\{/g,  '\\{')
    .replace(/\}/g,  '\\}')
    .replace(/~/g,   '\\textasciitilde{}')
    .replace(/\^/g,  '\\textasciicircum{}');
};

/** Strip leading # from a hex color string */
const stripHash = (hex) => (hex || '000000').replace(/^#/, '');


// ════════════════════════════════════════════════════════════
// SECTION 2 — CONFIGURATION MAPS
// ════════════════════════════════════════════════════════════

/** Page margins (in cm) keyed by density setting */
const MARGINS_BY_DENSITY = {
  compact:  { left: 2.0, right: 2.0, top: 1.5, bottom: 1.5 },
  balanced: { left: 2.5, right: 2.5, top: 2.0, bottom: 2.0 },
  spacious: { left: 3.0, right: 3.0, top: 2.5, bottom: 2.5 },
};

/** Base font size keyed by template variant */
const FONTSIZE_BY_VARIANT = {
  classic: '11pt',
  modern:  '11pt',  // Cover letters read better at 11pt
  minimal: '10pt',
};

/** fontspec-compatible font names for XeLaTeX */
const FONT_NAME_MAP = {
  'Cormorant Garamond': 'Cormorant Garamond',
  'DM Sans':            'DM Sans',
  'Lato':               'Lato',
  'Roboto':             'Roboto',
  'Roboto Slab':        'Roboto Slab',
  'Inter':              'Inter',
  'Source Sans Pro':    'Source Sans 3',
  'Open Sans':          'Open Sans',
  'Raleway':            'Raleway',
};

/**
 * Which contact types to include in a cover letter header.
 * Photo, DOB, nationality, driving licence are intentionally excluded.
 */
const ALLOWED_COVER_LETTER_CONTACT_TYPES = new Set([
  'email',
  'phone',
  'linkedin',
  'github',
  'website',
  'location',
]);


// ════════════════════════════════════════════════════════════
// SECTION 3 — PREAMBLE BUILDER
// Uses article class (not altacv) — cover letters don't need
// the CV-specific commands, but share the same color/font
// theme for visual consistency with the CV.
// ════════════════════════════════════════════════════════════

function buildCoverLetterPreamble(meta) {
  const layout   = meta.layout   ?? {};
  const colors   = meta.colors   ?? {};
  const fonts    = meta.fonts    ?? {};

  const margins    = MARGINS_BY_DENSITY[layout.density]           ?? MARGINS_BY_DENSITY.balanced;
  const fontSize   = FONTSIZE_BY_VARIANT[layout.template_variant] ?? '11pt';
  const headingFont = FONT_NAME_MAP[fonts.heading] ?? fonts.heading ?? 'Lato';
  const bodyFont    = FONT_NAME_MAP[fonts.body]    ?? fonts.body    ?? 'Lato';

  return `\\documentclass[${fontSize},a4paper,withhyper,normalphoto]{altacv}
%% Cover letter — auto-generated. Compile with:
%% latexmk -f -interaction=nonstopmode -pdfxe document.tex

% ── Packages ─────────────────────────────────────────────────
\\usepackage[a4paper, left=${margins.left}cm, right=${margins.right}cm, top=${margins.top}cm, bottom=${margins.bottom}cm]{geometry}
\\usepackage{hyperref}
\\usepackage{xcolor}
\\usepackage{fontawesome5}
\\usepackage{parskip}        % space between paragraphs, no indent
\\usepackage{microtype}      % better text justification
\\usepackage{setspace}       % line spacing control
\\usepackage{dashrule}       % horizontal rule under name block

% ── Fonts ────────────────────────────────────────────────────
\\iftutex
  \\usepackage{fontspec}
  \\setmainfont{${bodyFont}}
  \\setsansfont{${headingFont}}
  \\renewcommand{\\familydefault}{\\sfdefault}
\\else
  \\usepackage[utf8]{inputenc}
  \\usepackage[T1]{fontenc}
  \\usepackage[defaultsans]{lato}
  \\renewcommand{\\familydefault}{\\sfdefault}
\\fi

% ── Named colors (from JSON — matches CV color scheme) ───────
\\definecolor{cvPrimary}{HTML}{${stripHash(colors.primary)}}
\\definecolor{cvSecondary}{HTML}{${stripHash(colors.secondary)}}
\\definecolor{cvAccent}{HTML}{${stripHash(colors.accent)}}

% ── Hyperlink styling ─────────────────────────────────────────
\\hypersetup{
  colorlinks=true,
  urlcolor=cvPrimary,
  linkcolor=cvPrimary
}

% ── No page number on a single-page letter ───────────────────
\\pagestyle{empty}`;
}


// ════════════════════════════════════════════════════════════
// SECTION 4 — HEADER BLOCK BUILDER
// Name + title rule + contact line (no photo, no demographics)
// ════════════════════════════════════════════════════════════

/** Render one inline contact item for the cover letter contact line */
function buildOneInlineContactItem(item) {
  const val = escapeLatex(item.value);

  const normalizeUrl = (raw, prefix) =>
    raw.startsWith('http') ? raw : `${prefix}${raw}`;

  switch (item.type) {
    case 'email':
      return `\\faEnvelope~\\href{mailto:${item.value}}{${val}}`;

    case 'phone':
      return `\\faPhone~${val}`;

    case 'location':
      return `\\faMapMarker~${val}`;

    case 'linkedin': {
      const display = item.value.replace(/https?:\/\/(www\.)?linkedin\.com\/in\//i, '');
      const url     = normalizeUrl(item.value, 'https://linkedin.com/in/');
      return `\\faLinkedin~\\href{${url}}{${escapeLatex(display)}}`;
    }

    case 'github': {
      const display = item.value.replace(/https?:\/\/(www\.)?github\.com\//i, '');
      const url     = normalizeUrl(item.value, 'https://github.com/');
      return `\\faGithub~\\href{${url}}{${escapeLatex(display)}}`;
    }

    case 'website': {
      const url = normalizeUrl(item.value, 'https://');
      return `\\faGlobe~\\href{${url}}{${val}}`;
    }

    default:
      return '';
  }
}

function buildSignature(language){

  var kindRegardsText = kindRegardsInLanguages[language] || kindRegardsInLanguages["English"];

  return `\n\n\\begin{flushright}\\begin{minipage}{0.2\\textwidth}\\raggedright ${kindRegardsText}, \\\\[1em]\\includegraphics[width=3cm]{signature.png}\\\\[0em]\\end{minipage}\\end{flushright}`;
}

/** Build the name + tagline + contact-info header for the cover letter */
function buildCoverLetterHeader(header) {
  const allowedItems = (header.contact_items ?? [])
    .filter(item => ALLOWED_COVER_LETTER_CONTACT_TYPES.has(item.type));

  const contactLine = allowedItems
    .map(buildOneInlineContactItem)
    .filter(Boolean)
    .join('\\quad ');

  return `% ── Name block ───────────────────────────────────────────────
{\\Huge\\bfseries\\color{cvPrimary} ${escapeLatex(header.name)}}\\\\[4pt]
{\\large\\color{cvSecondary} ${escapeLatex(header.title)}}\\\\[6pt]
\\hdashrule{\\linewidth}{0.6pt}{1pt}\\\\[4pt]
{\\small ${contactLine}}
\\\\[14pt]`;
}


// ════════════════════════════════════════════════════════════
// SECTION 5 — BODY BUILDER
// Splits the cover letter text on blank lines → LaTeX paragraphs
// ════════════════════════════════════════════════════════════

/**
 * Convert the raw cover letter text to LaTeX paragraphs.
 * The text uses \r\n\r\n or \n\n as paragraph separators.
 * Each paragraph is escaped and separated by \medskip for
 * comfortable reading (parskip handles the actual spacing).
 */
function buildCoverLetterBody(rawText) {
  if (!rawText) return '';

  const paragraphs = rawText
    .split(/\r?\n\r?\n/)
    .map(p => p.replace(/\r?\n/g, ' ').trim())
    .filter(Boolean)
    .map(escapeLatex);

  return paragraphs.join('\n\n');
}


// ════════════════════════════════════════════════════════════
// SECTION 6 — FINAL ASSEMBLER
// ════════════════════════════════════════════════════════════

function buildFullCoverLetterDocument(cv) {
  const preamble = buildCoverLetterPreamble(cv.meta);
  const header   = buildCoverLetterHeader(cv.header);
  const body     = buildCoverLetterBody(cv.finalCoverLetter);
  const signature = buildSignature(cv.meta.languages);

  return `${preamble}

\\begin{document}
\\setstretch{1.15}

${header}

${body}

${signature}

\\end{document}
`;
}


// ════════════════════════════════════════════════════════════
// SECTION 7 — EXECUTE & RETURN
// ════════════════════════════════════════════════════════════

const latexDocument = buildFullCoverLetterDocument(cv);
const base64 = Buffer.from(latexDocument, "utf-8").toString("base64");

return [{ 
  json: {
    template: latexDocument,
    base64: base64,
    imageUrl: ""
  } 
}];
